static string Classify(int statusCode) => statusCode switch
{
    200 or 201 or 204 => "success",
    >= 300 and < 400  => "redirect",
    404               => "not found",
    >= 400 and < 500  => "client error",
    >= 500            => "server error",
    _                 => "unknown",
};

decimal Discount(Order order) => order switch
{
    { Customer.IsVip: true, Total: > 100m } => 0.15m,
    { Customer.IsVip: true }                => 0.10m,
    { Coupon: { Length: > 0 } code } when code.StartsWith("SAVE") => 0.05m,
    _                                       => 0m,
};

string Describe(string[] args) => args switch
{
    []                  => "no arguments",
    ["--help", ..]      => "help",
    [var only]          => $"one argument: {only}",
    [var first, .., var last] => $"{first} ... {last}",
};
